// Which direction an order trades.
enum OrderSide { BUY, SELL }

// Whether an order has a price limit or trades at any available price.
enum OrderType { LIMIT, MARKET }

// Lifecycle status of a single order.
enum OrderStatus {
    OPEN,              // resting in the book, no fills yet
    PARTIALLY_FILLED,  // some quantity matched, some still resting
    FILLED,            // fully matched
    CANCELLED          // unfilled remainder cancelled, e.g. an unfilled market order
}

// A trader's cash balance and per symbol share holdings.
class Account {
    private final String accountId;                                       // unique id
    private double cashBalance;                                             // available cash
    private final java.util.Map<String, Integer> holdings = new java.util.HashMap<>(); // symbol -> shares held

    public Account(String accountId, double cashBalance) {
        this.accountId = accountId;   // store id
        this.cashBalance = cashBalance; // store starting cash
    }

    public String getAccountId() { return accountId; }               // id getter
    public double getCashBalance() { return cashBalance; }              // cash getter
    public void adjustCash(double amount) { cashBalance += amount; }      // add or subtract cash
    public int getShares(String symbol) { return holdings.getOrDefault(symbol, 0); } // shares getter
    public void adjustShares(String symbol, int amount) { holdings.merge(symbol, amount, Integer::sum); } // add or subtract shares
}

// A single buy or sell order for one symbol.
class Order {
    private final String orderId;   // unique id, e.g. ORD1
    private final String accountId;  // who placed it
    private final String symbol;      // which stock
    private final OrderSide side;       // buy or sell
    private final OrderType type;         // limit or market
    private final double price;             // limit price, ignored for market orders
    private int remainingQuantity;            // shares still unmatched
    private OrderStatus status;                // current lifecycle state

    public Order(String orderId, String accountId, String symbol, OrderSide side, OrderType type, double price, int quantity) {
        this.orderId = orderId;         // store id
        this.accountId = accountId;       // store account
        this.symbol = symbol;               // store symbol
        this.side = side;                     // store side
        this.type = type;                       // store type
        this.price = price;                       // store limit price
        this.remainingQuantity = quantity;          // starts fully unfilled
        this.status = OrderStatus.OPEN;               // starts open
    }

    public String getOrderId() { return orderId; }                     // id getter
    public String getAccountId() { return accountId; }                    // account getter
    public String getSymbol() { return symbol; }                            // symbol getter
    public OrderSide getSide() { return side; }                               // side getter
    public OrderType getType() { return type; }                                // type getter
    public double getPrice() { return price; }                                  // price getter
    public int getRemainingQuantity() { return remainingQuantity; }               // remaining getter
    public void reduceQuantity(int amount) { remainingQuantity -= amount; }          // apply a fill
    public OrderStatus getStatus() { return status; }                                // status getter
    public void setStatus(OrderStatus status) { this.status = status; }                // status setter
}

// The result of matching a buy order against a sell order.
class Trade {
    private final String tradeId;      // unique id, e.g. TRD1
    private final String buyOrderId;     // the matched buy order
    private final String sellOrderId;      // the matched sell order
    private final double price;              // execution price, the resting order's price
    private final int quantity;                // shares exchanged in this trade

    public Trade(String tradeId, String buyOrderId, String sellOrderId, double price, int quantity) {
        this.tradeId = tradeId;         // store id
        this.buyOrderId = buyOrderId;     // store buy order
        this.sellOrderId = sellOrderId;     // store sell order
        this.price = price;                   // store execution price
        this.quantity = quantity;               // store executed quantity
    }

    public String getTradeId() { return tradeId; }         // id getter
    public double getPrice() { return price; }               // price getter
    public int getQuantity() { return quantity; }              // quantity getter
}

// Creates sequential, correctly-prefixed ids for orders and trades.
class OrderIdFactory {
    private int orderCounter = 0; // running id counter for orders
    private int tradeCounter = 0;   // running id counter for trades

    public String nextOrderId() {
        orderCounter++;                  // bump id counter
        return "ORD" + orderCounter;       // e.g. ORD1
    }

    public String nextTradeId() {
        tradeCounter++;                // bump id counter
        return "TRD" + tradeCounter;     // e.g. TRD1
    }
}

