// Strategy interface: the two questions that differ between order types.
interface OrderExecutionStrategy {
    boolean priceAcceptable(Order order, double restingPrice); // is this resting price tradeable for this order?
    boolean restsInBookIfUnfilled();                             // does leftover quantity wait, or cancel?
}

// A limit order only trades at its price or better, and rests if not fully filled.
class LimitOrderExecutionStrategy implements OrderExecutionStrategy {
    @Override
    public boolean priceAcceptable(Order order, double restingPrice) {
        if (order.getSide() == OrderSide.BUY) return restingPrice <= order.getPrice();  // buyer accepts at or below their limit
        return restingPrice >= order.getPrice();                                          // seller accepts at or above their limit
    }

    @Override
    public boolean restsInBookIfUnfilled() { return true; } // unfilled quantity waits in the book
}

// A market order trades at any available price, and never rests unfilled.
class MarketOrderExecutionStrategy implements OrderExecutionStrategy {
    @Override
    public boolean priceAcceptable(Order order, double restingPrice) {
        return true; // any price is acceptable, there is no limit
    }

    @Override
    public boolean restsInBookIfUnfilled() { return false; } // unfilled quantity simply cancels
}

// Observer interface: reacts to trading lifecycle events.
interface TradingObserver {
    void onOrderPlaced(Order order);                        // an order was accepted for matching
    void onOrderRejected(String accountId, String reason);    // an order could not be placed at all
    void onTradeExecuted(Trade trade);                          // a match produced a trade
}

// Simple observer that prints events to the console.
class ConsoleTradingObserver implements TradingObserver {
    @Override
    public void onOrderPlaced(Order order) {
        System.out.println("Order " + order.getOrderId() + " placed: " + order.getSide() + " " + order.getRemainingQuantity() + " " + order.getSymbol());
    }

    @Override
    public void onOrderRejected(String accountId, String reason) {
        System.out.println("Order rejected for " + accountId + ": " + reason);
    }

    @Override
    public void onTradeExecuted(Trade trade) {
        System.out.println("Trade " + trade.getTradeId() + " executed: " + trade.getQuantity() + " shares at " + trade.getPrice());
    }
}

