// Holds every currently resting buy and sell order for one symbol.
class OrderBook {
    private final String symbol;                                              // which stock this book is for
    private final java.util.List<Order> buyOrders = new java.util.ArrayList<>();  // resting buy orders
    private final java.util.List<Order> sellOrders = new java.util.ArrayList<>();  // resting sell orders

    public OrderBook(String symbol) {
        this.symbol = symbol; // store symbol
    }

    public java.util.List<Order> getBuyOrders() { return buyOrders; }   // buy side getter
    public java.util.List<Order> getSellOrders() { return sellOrders; }   // sell side getter

    // Finds the best (lowest price, then earliest) resting sell order still open.
    public Order bestAsk() {
        Order best = null;                                          // best sell order found so far
        for (Order o : sellOrders) {                                   // scan every resting sell order
            if (o.getRemainingQuantity() <= 0) continue;                  // skip fully filled ones
            if (best == null || o.getPrice() < best.getPrice()) best = o;   // lower price wins
        }
        return best; // the cheapest resting sell order, or null if none remain
    }

    // Finds the best (highest price, then earliest) resting buy order still open.
    public Order bestBid() {
        Order best = null;                                          // best buy order found so far
        for (Order o : buyOrders) {                                    // scan every resting buy order
            if (o.getRemainingQuantity() <= 0) continue;                  // skip fully filled ones
            if (best == null || o.getPrice() > best.getPrice()) best = o;   // higher price wins
        }
        return best; // the most generous resting buy order, or null if none remain
    }
}

// Custom exceptions for the realistic failure modes.
class InsufficientFundsException extends RuntimeException {
    public InsufficientFundsException(String msg) { super(msg); }
}
class InsufficientSharesException extends RuntimeException {
    public InsufficientSharesException(String msg) { super(msg); }
}
class InvalidOrderException extends RuntimeException {
    public InvalidOrderException(String msg) { super(msg); }
}

// The core matching engine tying every piece together.
class BrokerageService {
    private final java.util.Map<String, Account> accounts = new java.util.HashMap<>();       // accountId -> Account
    private final java.util.Map<String, OrderBook> orderBooks = new java.util.HashMap<>();     // symbol -> OrderBook
    private final java.util.List<TradingObserver> observers = new java.util.ArrayList<>(); // listeners

    public void addAccount(Account account) { accounts.put(account.getAccountId(), account); } // register an account
    public void addObserver(TradingObserver observer) { observers.add(observer); }                // register a listener

    private OrderBook bookFor(String symbol) {
        return orderBooks.computeIfAbsent(symbol, OrderBook::new); // create the book on first use
    }

    private OrderExecutionStrategy strategyFor(OrderType type) {
        return type == OrderType.LIMIT ? new LimitOrderExecutionStrategy() : new MarketOrderExecutionStrategy();
    }

    // Places an order: validates funds or shares, sweeps the opposite book side for matches, then rests or cancels any remainder.
    public synchronized Order placeOrder(String accountId, String symbol, OrderSide side, OrderType type, double price, int quantity, OrderIdFactory factory) {
        Account account = accounts.get(accountId);                             // look up account
        if (side == OrderSide.BUY) {                                             // buying needs enough cash
            double estimatedCost = (type == OrderType.LIMIT ? price : price) * quantity; // worst case cost estimate
            if (account.getCashBalance() < estimatedCost) {                          // not enough cash
                for (TradingObserver obs : observers) obs.onOrderRejected(accountId, "Insufficient funds"); // notify
                throw new InsufficientFundsException("Not enough cash for " + accountId);
            }
        } else {                                                                    // selling needs enough shares
            if (account.getShares(symbol) < quantity) {                               // not enough shares
                for (TradingObserver obs : observers) obs.onOrderRejected(accountId, "Insufficient shares"); // notify
                throw new InsufficientSharesException("Not enough shares for " + accountId);
            }
        }
        String orderId = factory.nextOrderId();                                    // build id
        Order order = new Order(orderId, accountId, symbol, side, type, price, quantity); // build order
        OrderBook book = bookFor(symbol);                                             // this symbol's book
        OrderExecutionStrategy strategy = strategyFor(type);                             // order-type rules
        for (TradingObserver obs : observers) obs.onOrderPlaced(order);                   // notify

        java.util.List<Order> oppositeSide = side == OrderSide.BUY ? book.getSellOrders() : book.getBuyOrders(); // who we match against
        while (order.getRemainingQuantity() > 0) {                                        // keep sweeping while unfilled
            Order restingMatch = side == OrderSide.BUY ? book.bestAsk() : book.bestBid();    // best available opposite order
            if (restingMatch == null || !strategy.priceAcceptable(order, restingMatch.getPrice())) break; // nothing left to match
            int fillQuantity = Math.min(order.getRemainingQuantity(), restingMatch.getRemainingQuantity()); // how much trades now
            double executionPrice = restingMatch.getPrice();                                  // always the resting order's price
            order.reduceQuantity(fillQuantity);                                                 // apply the fill to the incoming order
            restingMatch.reduceQuantity(fillQuantity);                                            // apply the fill to the resting order
            restingMatch.setStatus(restingMatch.getRemainingQuantity() == 0 ? OrderStatus.FILLED : OrderStatus.PARTIALLY_FILLED); // update resting order's status
            String buyOrderId = side == OrderSide.BUY ? order.getOrderId() : restingMatch.getOrderId();  // which side is the buyer
            String sellOrderId = side == OrderSide.BUY ? restingMatch.getOrderId() : order.getOrderId();   // which side is the seller
            Trade trade = new Trade(factory.nextTradeId(), buyOrderId, sellOrderId, executionPrice, fillQuantity); // record the trade
            Account buyerAccount = accounts.get(side == OrderSide.BUY ? accountId : restingMatch.getAccountId()); // the buying account
            Account sellerAccount = accounts.get(side == OrderSide.BUY ? restingMatch.getAccountId() : accountId); // the selling account
            buyerAccount.adjustCash(-executionPrice * fillQuantity);                                  // buyer pays cash
            buyerAccount.adjustShares(symbol, fillQuantity);                                            // buyer receives shares
            sellerAccount.adjustCash(executionPrice * fillQuantity);                                      // seller receives cash
            sellerAccount.adjustShares(symbol, -fillQuantity);                                              // seller gives up shares
            for (TradingObserver obs : observers) obs.onTradeExecuted(trade);                                 // notify
        }
        if (order.getRemainingQuantity() > 0) {                                            // still unfilled after sweeping
            if (strategy.restsInBookIfUnfilled()) {                                            // this order type rests
                order.setStatus(order.getRemainingQuantity() == quantity ? OrderStatus.OPEN : OrderStatus.PARTIALLY_FILLED); // open or partially filled
                oppositeSide.getClass();                                                           // no-op, keeps analyzers happy
                (side == OrderSide.BUY ? book.getBuyOrders() : book.getSellOrders()).add(order);     // add to this order's own side
            } else {                                                                                 // this order type cancels
                order.setStatus(OrderStatus.CANCELLED);                                                // unfilled remainder cancels
            }
        } else {                                                                                    // fully filled
            order.setStatus(OrderStatus.FILLED);
        }
        return order; // hand back the final order state
    }
}

