using namespace std;

// Holds every currently resting buy and sell order for one symbol.
class OrderBook {
public:
    string symbol;               // which stock this book is for
    vector<Order> buyOrders;        // resting buy orders
    vector<Order> sellOrders;         // resting sell orders

    OrderBook() {}
    OrderBook(string sym) : symbol(sym) {}

    Order* bestAsk() {
        Order* best = nullptr;                                        // best sell order found so far
        for (auto& o : sellOrders) {                                     // scan every resting sell order
            if (o.remainingQuantity <= 0) continue;                        // skip fully filled ones
            if (best == nullptr || o.price < best->price) best = &o;         // lower price wins
        }
        return best; // the cheapest resting sell order, or nullptr if none remain
    }

    Order* bestBid() {
        Order* best = nullptr;                                        // best buy order found so far
        for (auto& o : buyOrders) {                                      // scan every resting buy order
            if (o.remainingQuantity <= 0) continue;                        // skip fully filled ones
            if (best == nullptr || o.price > best->price) best = &o;         // higher price wins
        }
        return best; // the most generous resting buy order, or nullptr if none remain
    }
};

// Custom exceptions for the realistic failure modes.
class InsufficientFundsException : public runtime_error {
public: InsufficientFundsException(const string& msg) : runtime_error(msg) {}
};
class InsufficientSharesException : public runtime_error {
public: InsufficientSharesException(const string& msg) : runtime_error(msg) {}
};
class InvalidOrderException : public runtime_error {
public: InvalidOrderException(const string& msg) : runtime_error(msg) {}
};

// The core matching engine tying every piece together.
class BrokerageService {
    map<string, Account> accounts;         // accountId -> Account
    map<string, OrderBook> orderBooks;    // symbol -> OrderBook
    vector<shared_ptr<TradingObserver>> observers; // listeners

    OrderBook& bookFor(string symbol) {
        if (orderBooks.find(symbol) == orderBooks.end()) orderBooks[symbol] = OrderBook(symbol); // create on first use
        return orderBooks.at(symbol);
    }

    shared_ptr<OrderExecutionStrategy> strategyFor(OrderType type) {
        if (type == OrderType::LIMIT) return make_shared<LimitOrderExecutionStrategy>();
        return make_shared<MarketOrderExecutionStrategy>();
    }

public:
    void addAccount(Account account) { accounts.insert({account.accountId, account}); } // register an account
    void addObserver(shared_ptr<TradingObserver> observer) { observers.push_back(observer); } // register a listener

    Order placeOrder(string accountId, string symbol, OrderSide side, OrderType type, double price, int quantity, OrderIdFactory& factory) {
        Account& account = accounts.at(accountId); // look up account
        if (side == OrderSide::BUY) {                 // buying needs enough cash
            double estimatedCost = price * quantity;     // worst case cost estimate
            if (account.cashBalance < estimatedCost) {      // not enough cash
                for (auto& obs : observers) obs->onOrderRejected(accountId, "Insufficient funds"); // notify
                throw InsufficientFundsException("Not enough cash for " + accountId);
            }
        } else {                                        // selling needs enough shares
            if (account.getShares(symbol) < quantity) {     // not enough shares
                for (auto& obs : observers) obs->onOrderRejected(accountId, "Insufficient shares"); // notify
                throw InsufficientSharesException("Not enough shares for " + accountId);
            }
        }
        string orderId = factory.nextOrderId();          // build id
        Order order(orderId, accountId, symbol, side, type, price, quantity); // build order
        OrderBook& book = bookFor(symbol);                  // this symbol's book
        auto strategy = strategyFor(type);                    // order-type rules
        for (auto& obs : observers) obs->onOrderPlaced(order);  // notify

        while (order.remainingQuantity > 0) {                    // keep sweeping while unfilled
            Order* restingMatch = (side == OrderSide::BUY) ? book.bestAsk() : book.bestBid(); // best available opposite order
            if (restingMatch == nullptr || !strategy->priceAcceptable(order, restingMatch->price)) break; // nothing left to match
            int fillQuantity = min(order.remainingQuantity, restingMatch->remainingQuantity); // how much trades now
            double executionPrice = restingMatch->price;              // always the resting order's price
            order.reduceQuantity(fillQuantity);                          // apply the fill to the incoming order
            restingMatch->reduceQuantity(fillQuantity);                    // apply the fill to the resting order
            restingMatch->status = (restingMatch->remainingQuantity == 0) ? OrderStatus::FILLED : OrderStatus::PARTIALLY_FILLED; // update resting order's status
            string buyOrderId = (side == OrderSide::BUY) ? order.orderId : restingMatch->orderId;   // which side is the buyer
            string sellOrderId = (side == OrderSide::BUY) ? restingMatch->orderId : order.orderId;    // which side is the seller
            Trade trade(factory.nextTradeId(), buyOrderId, sellOrderId, executionPrice, fillQuantity);  // record the trade
            Account& buyerAccount = accounts.at((side == OrderSide::BUY) ? accountId : restingMatch->accountId);  // the buying account
            Account& sellerAccount = accounts.at((side == OrderSide::BUY) ? restingMatch->accountId : accountId);   // the selling account
            buyerAccount.adjustCash(-executionPrice * fillQuantity);          // buyer pays cash
            buyerAccount.adjustShares(symbol, fillQuantity);                    // buyer receives shares
            sellerAccount.adjustCash(executionPrice * fillQuantity);              // seller receives cash
            sellerAccount.adjustShares(symbol, -fillQuantity);                     // seller gives up shares
            for (auto& obs : observers) obs->onTradeExecuted(trade);                 // notify
        }
        if (order.remainingQuantity > 0) {                                      // still unfilled after sweeping
            if (strategy->restsInBookIfUnfilled()) {                              // this order type rests
                order.status = (order.remainingQuantity == quantity) ? OrderStatus::OPEN : OrderStatus::PARTIALLY_FILLED; // open or partially filled
                (side == OrderSide::BUY ? book.buyOrders : book.sellOrders).push_back(order); // add to this order's own side
            } else {                                                                // this order type cancels
                order.status = OrderStatus::CANCELLED;                                // unfilled remainder cancels
            }
        } else {                                                                   // fully filled
            order.status = OrderStatus::FILLED;
        }
        return order; // hand back the final order state
    }
};

