    public List<Order> getSellOrders() { return sellOrders; }

    public Order bestAsk() {
        Order best = null;
        for (Order o : sellOrders) {
            if (o.getRemainingQuantity() <= 0) continue;
            if (best == null || o.getPrice() < best.getPrice()) best = o;
        }
        return best;
    }

    public Order bestBid() {
        Order best = null;
        for (Order o : buyOrders) {
            if (o.getRemainingQuantity() <= 0) continue;
            if (best == null || o.getPrice() > best.getPrice()) best = o;
        }
        return best;
    }
}

