class BrokerageService {
    private final Map<String, Account> accounts = new HashMap<>();
    private final Map<String, OrderBook> orderBooks = new HashMap<>();
    private final List<TradingObserver> observers = new ArrayList<>();

    public void addAccount(Account account) { accounts.put(account.getAccountId(), account); }
    public void addObserver(TradingObserver observer) { observers.add(observer); }

    private OrderBook bookFor(String symbol) {
        return orderBooks.computeIfAbsent(symbol, OrderBook::new);
    }

    private OrderExecutionStrategy strategyFor(OrderType type) {
        return type == OrderType.LIMIT ? new LimitOrderExecutionStrategy() : new MarketOrderExecutionStrategy();
    }

    public synchronized Order placeOrder(String accountId, String symbol, OrderSide side, OrderType type, double price, int quantity, OrderIdFactory factory) {
        Account account = accounts.get(accountId);
        if (side == OrderSide.BUY) {
            double estimatedCost = price * quantity;
            if (account.getCashBalance() < estimatedCost) {
                for (TradingObserver obs : observers) obs.onOrderRejected(accountId, "Insufficient funds");
                throw new InsufficientFundsException("Not enough cash for " + accountId);
            }
        } else {
            if (account.getShares(symbol) < quantity) {
                for (TradingObserver obs : observers) obs.onOrderRejected(accountId, "Insufficient shares");
                throw new InsufficientSharesException("Not enough shares for " + accountId);
            }
        }
        String orderId = factory.nextOrderId();
        Order order = new Order(orderId, accountId, symbol, side, type, price, quantity);
        OrderBook book = bookFor(symbol);
        OrderExecutionStrategy strategy = strategyFor(type);
        for (TradingObserver obs : observers) obs.onOrderPlaced(order);

        while (order.getRemainingQuantity() > 0) {
            Order restingMatch = side == OrderSide.BUY ? book.bestAsk() : book.bestBid();
            if (restingMatch == null || !strategy.priceAcceptable(order, restingMatch.getPrice())) break;
            int fillQuantity = Math.min(order.getRemainingQuantity(), restingMatch.getRemainingQuantity());
            double executionPrice = restingMatch.getPrice();
            order.reduceQuantity(fillQuantity);
            restingMatch.reduceQuantity(fillQuantity);
            restingMatch.setStatus(restingMatch.getRemainingQuantity() == 0 ? OrderStatus.FILLED : OrderStatus.PARTIALLY_FILLED);
            String buyOrderId = side == OrderSide.BUY ? order.getOrderId() : restingMatch.getOrderId();
            String sellOrderId = side == OrderSide.BUY ? restingMatch.getOrderId() : order.getOrderId();
            Trade trade = new Trade(factory.nextTradeId(), buyOrderId, sellOrderId, executionPrice, fillQuantity);
            Account buyerAccount = accounts.get(side == OrderSide.BUY ? accountId : restingMatch.getAccountId());
            Account sellerAccount = accounts.get(side == OrderSide.BUY ? restingMatch.getAccountId() : accountId);
            buyerAccount.adjustCash(-executionPrice * fillQuantity);
            buyerAccount.adjustShares(symbol, fillQuantity);
            sellerAccount.adjustCash(executionPrice * fillQuantity);
            sellerAccount.adjustShares(symbol, -fillQuantity);
            for (TradingObserver obs : observers) obs.onTradeExecuted(trade);
        }
        if (order.getRemainingQuantity() > 0) {
            if (strategy.restsInBookIfUnfilled()) {
                order.setStatus(order.getRemainingQuantity() == quantity ? OrderStatus.OPEN : OrderStatus.PARTIALLY_FILLED);
                (side == OrderSide.BUY ? book.getBuyOrders() : book.getSellOrders()).add(order);
            } else {
                order.setStatus(OrderStatus.CANCELLED);
            }
        } else {
            order.setStatus(OrderStatus.FILLED);
        }
        return order;
    }
}

