            restingMatch->status = (restingMatch->remainingQuantity == 0) ? OrderStatus::FILLED : OrderStatus::PARTIALLY_FILLED;
            string buyOrderId = (side == OrderSide::BUY) ? order.orderId : restingMatch->orderId;
            string sellOrderId = (side == OrderSide::BUY) ? restingMatch->orderId : order.orderId;
            Trade trade(factory.nextTradeId(), buyOrderId, sellOrderId, executionPrice, fillQuantity);
            Account& buyerAccount = accounts.at((side == OrderSide::BUY) ? accountId : restingMatch->accountId);
            Account& sellerAccount = accounts.at((side == OrderSide::BUY) ? restingMatch->accountId : accountId);
            buyerAccount.adjustCash(-executionPrice * fillQuantity);
            buyerAccount.adjustShares(symbol, fillQuantity);
            sellerAccount.adjustCash(executionPrice * fillQuantity);
            sellerAccount.adjustShares(symbol, -fillQuantity);
            for (auto& obs : observers) obs->onTradeExecuted(trade);
        }
        if (order.remainingQuantity > 0) {
            if (strategy->restsInBookIfUnfilled()) {
                order.status = (order.remainingQuantity == quantity) ? OrderStatus::OPEN : OrderStatus::PARTIALLY_FILLED;
                (side == OrderSide::BUY ? book.buyOrders : book.sellOrders).push_back(order);
            } else {
                order.status = OrderStatus::CANCELLED;
            }
        } else {
            order.status = OrderStatus::FILLED;
        }
        return order;
    }
};

